const entities = $json.output.entities || [];
const out = [];
const seen = new Set();

// Helper: Escape double quotes to prevent breaking JSON downstream
const clean = (str) => {
  if (typeof str !== 'string') return str;
  return str.replace(/"/g, '\\"').trim();
};

// Safe access to external variables (prevents crashes if nodes/data are missing)
const userId = $('RemapInput').first()?.json?.userId;
const globalCountry = $input.first()?.json?.output?.entities?.[0]?.entity1_country;

for (const e of entities) {

  // --- Entity 1 Processing ---
  const e1Name = e.entity1 ? String(e.entity1) : ''; // Ensure string

  if (e1Name.trim()) {
    const key = `${e1Name}|${e.entity1_type}`;
    if (!seen.has(key)) {
      seen.add(key);
      out.push({ 
        json: { 
          query: clean(e1Name), 
          entityType: clean(e.entity1_type),
          relationship: clean(e1Name), 
          userId: userId,
          country: globalCountry
        } 
      });
    }
  }

  // --- Entity 2 Processing ---
  const e2Name = e.entity2 ? String(e.entity2) : ''; // Ensure string

  if (e2Name.trim()) {
    const key = `${e2Name}|${e.entity2_type}`;
    if (!seen.has(key)) {
      seen.add(key);

      // Safe relationship string construction
      const relString = `${e1Name} ${e.type_of_relationship || ''} ${e2Name}`;

      out.push({ 
        json: { 
          query: clean(e2Name), 
          entityType: clean(e.entity2_type),
          relationship: clean(relString),
          userId: userId,        // Added for schema consistency
          country: globalCountry // Added for schema consistency
        } 
      });
    }
  }
}

return out;

// Remap incoming OpenAI-like request to your OSINT input
// Потрібен Bearer; callback_url лише з дозволених хостів
const msgs = $json.body?.messages || [];

const userHistory = [];
for (const msg of msgs) {
  if (msg.role === 'user') {
    let content = msg.content || '';
    if (Array.isArray(content)) {
      const textItem = content.find(i => i.type === 'text');
      content = textItem?.text || '';
    }
    const m = content.match(/<selected_text>(.*?)<\/selected_text>/s);
    const extracted = m ? m[1].trim() : content;

    const normalized = typeof extracted === 'string'
      ? extracted.replace(/\r?\n+/g, ' ')
          .replace(/\\n+/g, ' ')
          .replace(/\s{2,}/g, ' ')
          .replace(/"/g, '\\"')
          .trim()
      : '';

    if (normalized) userHistory.push(normalized);
  }
}

const lastContent = userHistory[userHistory.length - 1] || '';
const cleanContent = lastContent.replace(/^!NEW!\s*/, '');

function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let out = 0;
  for (let i = 0; i < a.length; i++) out |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return out === 0;
}
const authHeader = $json.headers['authorization'] || $json.headers['Authorization'] || '';
const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7).trim() : '';
const expected = String($env.WEBHOOK_SECRET || '').trim();
if (!expected || expected.length < 16) {
  throw new Error('Unauthorized: set WEBHOOK_SECRET in n8n env (≥16 chars)');
}
if (!token || !safeEqual(token, expected)) {
  throw new Error('Unauthorized: invalid Bearer token');
}
const userId = token;

const job_id = $json.body?.job_id || $json.body?.userId || userId;
const filename = $json.body?.filename || 'report.md';

function sanitizeCallbackUrl(raw) {
  const url = String(raw || '').trim();
  if (!url) return '';
  let parsed;
  try { parsed = new URL(url); } catch {
    throw new Error('Invalid callback_url');
  }
  if (parsed.protocol !== 'https:') {
    throw new Error('callback_url must use https');
  }
  const host = parsed.hostname.toLowerCase();
  if (
    host === 'localhost' ||
    host.endsWith('.local') ||
    host === '::1' ||
    /^(127\.|10\.|172\.(1[6-9]|2\d|3[01])\.|192\.168\.|169\.254\.|0\.0\.0\.0)/.test(host)
  ) {
    throw new Error('callback_url host is not allowed');
  }
  // Comma-separated hosts from env, or teaching placeholder host only
  const allowed = String($env.CALLBACK_URL_ALLOWED_HOSTS || 'YOUR_API_HOST.example.com')
    .split(',')
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
  const ok = allowed.some((a) => host === a || host.endsWith('.' + a));
  if (!ok) {
    throw new Error('callback_url host not in CALLBACK_URL_ALLOWED_HOSTS allowlist');
  }
  return parsed.toString();
}

const callback_url = sanitizeCallbackUrl($json.body?.callback_url);

const out = {
  chatInput: cleanContent,
  userId,
  job_id,
  callback_url,
  filename
};

if (userHistory.length > 1) {
  out.history = userHistory;
}

return { json: out };

// Получаем все items (массив из 3 объектов)
const inputItems = items;

// Извлекаем relationship из нужных items
const mainRelationship = inputItems[0].json.relationship;  // Только из первого
const searchRelationships = inputItems.map(item => item.json.relationship);

// Возвращаем один item с структурированными данными
return [{
  json: {
    main_relationship: mainRelationship,
    search_queries: searchRelationships,
    entityType: inputItems[0].json.entityType,
    userId: $input.first().json.userId,
    country: $input.first().json.country
  }
}];

// Берём все items (до 11)
const allItems = items.map(item => item.json);

// Объединяем все json в один объект (последние перезапишут дубликаты)
const mergedJson = allItems.reduce((acc, current) => ({ ...acc, ...current }), {});

// Возвращаем один item
return [{ json: mergedJson }];

// Получаем все items (массив любого размера)
const inputItems = items || [];  // Fallback to empty array if undefined

// Проверяем на пустоту
if (!inputItems.length) {
  return [{ json: { search_results: 'No results found' } }];
}

// Извлекаем и форматируем результаты (предполагаем структуру item.json.results как массив объектов)
let allResults = [];
inputItems.forEach(item => {
  const data = item.json || {};  // Fallback if no json
  if (data.results && Array.isArray(data.results)) {
    allResults = allResults.concat(data.results);
  }
});

// Форматируем в строку (title + content + URL для каждого)
const searchResultsString = allResults.map(result => {
  return (result.title || 'N/A') + '\n' + (result.content || 'N/A') + '\nURL: ' + (result.url || 'N/A');
}).join('\n\n');

// Возвращаем один item с объединёнными результатами
return [{ json: { search_results: searchResultsString } }];

const a = $input.first().json?.choices?.[0]?.message?.content;
const b = $input.all()[1]?.json?.output;
const toText = v => (typeof v === 'string' ? v.trim() : (v ? JSON.stringify(v, null, 2) : ''));
const web_data = toText(a); 
const sanc_data = toText(b);

const { main_relationship: query, userId } = $('Code3').first().json ?? {};
return [{ json: { userId, query, web_data, sanc_data } }];

